                                     `mute_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '禁言原因',
                                     `start_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始时间',
                                     `end_time` datetime DEFAULT NULL COMMENT '结束时间',
                                     `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 0失效 1生效',
                                     `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                     PRIMARY KEY (`id`),
                                     KEY `idx_user_id_status` (`user_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='聊天室禁言表';

DROP TABLE IF EXISTS `tb_comment`;

CREATE TABLE `tb_comment` (
                              `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
                              `user_id` int NOT NULL COMMENT '评论用户Id',
                              `topic_id` int DEFAULT NULL COMMENT '评论主题id',
                              `comment_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评论内容',
                              `reply_user_id` int DEFAULT NULL COMMENT '回复用户id',
                              `parent_id` int DEFAULT NULL COMMENT '父评论id',
                              `type` tinyint NOT NULL COMMENT '评论类型 1.文章 2.友链 3.说说',
                              `is_delete` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除  0否 1是',
                              `is_review` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否审核',
                              `create_time` datetime NOT NULL COMMENT '评论时间',
                              `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                              PRIMARY KEY (`id`) USING BTREE,
                              KEY `fk_comment_user` (`user_id`) USING BTREE,
                              KEY `fk_comment_parent` (`parent_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=756 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `tb_friend_link`;

CREATE TABLE `tb_friend_link` (
                                  `id` int NOT NULL AUTO_INCREMENT,
                                  `link_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '链接名',
                                  `link_cover` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '网站封面',
                                  `link_address` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '链接地址',
                                  `link_intro` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '链接介绍',
                                  `link_status` tinyint NOT NULL DEFAULT '1' COMMENT '审核状态 0=待审核 1=已通过 2=已拒绝',
                                  `create_time` datetime NOT NULL COMMENT '创建时间',
                                  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                  PRIMARY KEY (`id`) USING BTREE,
                                  KEY `fk_friend_link_user` (`link_name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `tb_love_config`;

CREATE TABLE `tb_love_config` (
                                  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
                                  `title` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '页面标题',
                                  `subtitle` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '页面副标题',
                                  `background` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '背景图地址',
                                  `start_time` datetime NOT NULL COMMENT '开始时间',
                                  `anniversary_time` datetime DEFAULT NULL COMMENT '纪念日时间',
                                  `anniversary_title` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纪念日标题',
                                  `is_enabled` tinyint NOT NULL DEFAULT '1' COMMENT '是否启用 0否 1是',
                                  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                                  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='纪念页基础配置';

DROP TABLE IF EXISTS `tb_love_letter`;

CREATE TABLE `tb_love_letter` (
                                  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
                                  `letter_title` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '信件标题',
                                  `letter_content` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '信件正文',
                                  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
                                  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='飞书传信正文';

DROP TABLE IF EXISTS `tb_mail_subscribe`;

CREATE TABLE `tb_mail_subscribe` (
                                     `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
                                     `email` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '邮箱',
                                     `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 0退订 1订阅中',
                                     `subscribe_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'article' COMMENT '订阅类型',
                                     `token` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '确认或退订token',
                                     `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                     PRIMARY KEY (`id`),
                                     UNIQUE KEY `uk_email_type` (`email`,`subscribe_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='邮件订阅表';

DROP TABLE IF EXISTS `tb_menu`;

CREATE TABLE `tb_menu` (
                           `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
                           `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单名',
                           `path` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单路径',
                           `component` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组件',
                           `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单icon',
                           `create_time` datetime NOT NULL COMMENT '创建时间',
                           `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                           `order_num` tinyint(1) NOT NULL COMMENT '排序',
                           `parent_id` int DEFAULT NULL COMMENT '父id',
                           `is_hidden` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否隐藏  0否1是',
                           PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=222 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

