DROP TABLE IF EXISTS `tb_message`;

CREATE TABLE `tb_message` (
                              `id` int NOT NULL AUTO_INCREMENT COMMENT '主键id',
                              `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '昵称',
                              `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '头像',
                              `message_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '留言内容',
                              `ip_address` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户ip',
                              `ip_source` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户地址',
                              `time` tinyint(1) DEFAULT NULL COMMENT '弹幕速度',
                              `is_review` tinyint NOT NULL DEFAULT '1' COMMENT '是否审核 0需要审核 1不需要审核',
                              `create_time` datetime NOT NULL COMMENT '发布时间',
                              `update_time` datetime DEFAULT NULL COMMENT '修改时间',
                              PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=359277 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `tb_operation_log`;

CREATE TABLE `tb_operation_log` (
                                    `id` int NOT NULL AUTO_INCREMENT COMMENT '主键id',
                                    `opt_module` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作模块',
                                    `opt_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作类型',
                                    `opt_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作url',
                                    `opt_method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作方法',
                                    `opt_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作描述',
                                    `request_param` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请求参数',
                                    `request_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请求方式',
                                    `response_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '返回数据',
                                    `user_id` int NOT NULL COMMENT '用户id',
                                    `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户昵称',
                                    `ip_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作ip',
                                    `ip_source` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作地址',
                                    `create_time` datetime NOT NULL COMMENT '创建时间',
                                    `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1732 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

INSERT INTO `tb_operation_log` (`id`, `opt_module`, `opt_type`, `opt_url`, `opt_method`, `opt_desc`, `request_param`, `request_method`, `response_data`, `user_id`, `nickname`, `ip_address`, `ip_source`, `create_time`, `update_time`) VALUES
                                                                                                                                                                                                                                             (1727, '分类模块', '新增或修改', '/admin/categories', 'com.chen.blog.module.category.controller.CategoryController.saveOrUpdateCategory', '添加或修改分类', '[{"categoryName":"测试"}]', 'POST', '{"code":20000,"flag":true,"message":"操作成功"}', 1, '任子双', '127.0.0.1', '', '2026-08-13 15:04:59', NULL),
                                                                                                                                                                                                                                             (1728, '标签模块', '新增或修改', '/admin/tags', 'com.chen.blog.module.tag.controller.TagController.saveOrUpdateTag', '添加或修改标签', '[{"tagName":"测试"}]', 'POST', '{"code":20000,"flag":true,"message":"操作成功"}', 1, '任子双', '127.0.0.1', '', '2026-08-13 15:05:03', NULL),
                                                                                                                                                                                                                                             (1729, '文章模块', '新增或修改', '/admin/articles', 'com.chen.blog.module.article.controller.ArticleController.saveOrUpdateArticle', '添加或修改文章', '[{"aiSummary":"","aiSummaryStatus":0,"articleContent":"内容测试","articleCover":"","articleTitle":"测试文字","categoryName":"测试","isTop":0,"originalUrl":"","seoDescription":"","seoKeywords":"","seoOgDescription":"","seoTitle":"","status":3,"tagNameList":[],"type":1}]', 'POST', '{"code":20000,"flag":true,"message":"操作成功"}', 1, '任子双', '127.0.0.1', '', '2026-08-13 15:32:59', NULL),
                                                                                                                                                                                                                                             (1730, '文章模块', '新增或修改', '/admin/articles', 'com.chen.blog.module.article.controller.ArticleController.saveOrUpdateArticle', '添加或修改文章', '[{"aiSummary":"该博客系统已开源，采用前后端分离架构，基于Sa Token轻量级鉴权，涵盖文章、评论、说说、相册、聊天室等完整功能。技术栈包括Spring Boot、Vue 2/3、MyBatis Plus、Redis、Elasticsearch及消息队列等，支持三端适配、主题切换与全文搜索，并提供详细部署与贡献指南，遵循MIT协议。","aiSummaryStatus":1,"aiSummaryTime":1786438815000,"articleContent":"# RenZS Blog - 基于 Sa-Token 的前后端分离博客系统\\n\\n<div align=\\"center\\">\\n\\n![Spring Boot](https://img.shields.io/badge/Spring%20Boot-2.4.1-brightgreen.svg)\\n![Sa-Token](https://img.shields.io/badge/Sa--Token-1.39.0-blue.svg)\\n![Vue](https://img.shields.io/badge/Vue-3.4.21-green.svg)\\n![MySQL](https://img.shields.io/badge/MySQL-8.0-orange.svg)\\n![License](https://img.shields.io/badge/License-MIT-yellow.svg)\\n\\n一个功能完善的个人博客系统，支持文章发布、评论互动、说说动态、相册展示、在线聊天等功能。\\n\\n[在线演示](https://www.renzs.top/) · [问题反馈](https://gitee.com/chen_fuyun/blog-satoken/issues) · [贡献指南](#贡献指南)\\n\\n</div>\\n\\n---\\n\\n## ✨ 特性\\n\\n- 🔐 **轻量级鉴权** - 使用 Sa-Token 替代 Spring Security，配置简单、性能优越\\n- 🎨 **三端适配** - 后台管理（Vue 2）、博客前台（Vue 3）、移动端 App\\n- 📝 **富文本编辑** - Markdown 编辑器，支持代码高亮、LaTeX 公式、任务列表\\n- 💬 **实时通讯** - WebSocket 聊天室、消息通知\\n- 🔍 **全文搜索** - Elasticsearch 支持文章快速检索\\n- 🎯 **消息队列** - RocketMQ + RabbitMQ 异步处理\\n- 🌓 **主题切换** - 支持明暗主题无缝切换\\n- 📱 **响应式设计** - 完美适配桌面、平板、移动端\\n- 🚀 **高性能** - Redis 缓存、接口限流、SQL 优化\\n\\n---\\n\\n## 📦 项目结构\\n\\n```\\nblog-satoken/\\n├── renzs-blog-satoken/          # 后端 Spring Boot 项目\\n│   ├── src/main/java/com/chen/blog/\\n│   │   ├── common/              # 公共模块\\n│   │   │   ├── satoken/         # Sa-Token 鉴权配置\\n│   │   │   ├── config/          # 全局配置\\n│   │   │   ├── handler/         # 异常处理器\\n│   │   │   └── util/            # 工具类\\n│   │   ├── module/              # 业务模块\\n│   │   │   ├── user/            # 用户模块（登录、注册、OAuth）\\n│   │   │   ├── article/         # 文章模块\\n│   │   │   ├── comment/         # 评论模块\\n│   │   │   ├── talk/            # 说说模块\\n│   │   │   ├── album/           # 相册模块\\n│   │   │   ├── notice/          # 通知模块（WebSocket）\\n│   │   │   └── ...\\n│   │   └── consumer/            # 消息队列消费者\\n│   └── src/main/resources/\\n│       ├── application.yml      # 主配置文件\\n│       ├── application-dev.yml  # 开发环境配置\\n│       └── application-pro.yml  # 生产环境配置\\n├── blog-front/\\n│   ├── admin/                   # 后台管理系统（Vue 2 + Element UI）\\n│   ├── blog-vue3/               # 博客前台（Vue 3 + Vuetify + Element Plus）\\n│   └── blog-app/                # 移动端 App\\n└── README.md\\n```\\n\\n---\\n\\n## 🛠️ 技术栈\\n\\n### 后端技术\\n\\n| 技术 | 版本 | 说明 |\\n|---|---|---|\\n| Spring Boot | 2.4.1 | 核心框架 |\\n| Sa-Token | 1.39.0 | 鉴权框架（Cookie 模式） |\\n| MyBatis-Plus | 3.4.0 | ORM 框架 |\\n| MySQL | 8.0+ | 关系型数据库 |\\n| Redis | 6.0+ | 缓存 + 会话存储 |\\n| Elasticsearch | 7.x | 全文搜索引擎 |\\n| RocketMQ | 2.1.1 | 分布式消息队列 |\\n| RabbitMQ | - | 消息队列 |\\n| Swagger | 2.0.7 (Knife4j) | API 文档 |\\n| WebSocket | - | 实时通讯 |\\n| Hutool | 5.7.5 | Java 工具库 |\\n| Lombok | - | 简化代码 |\\n| XXL-Job | 2.3.1 | 分布式任务调度 |\\n| Aliyun OSS / 腾讯云 COS | - | 对象存储 |\\n\\n### 前端技术\\n\\n#### 博客前台（Vue 3）\\n\\n| 技术 | 版本 | 说明 |\\n|---|---|---|\\n| Vue | 3.4.21 | 渐进式框架 |\\n| TypeScript | 5.4.0 | 类型安全 |\\n| Vite | 5.1.6 | 构建工具 |\\n| Vue Router | 4.3.0 | 路由管理 |\\n| Pinia | 2.1.7 | 状态管理 |\\n| Vuetify | 3.5.8 | Material Design UI |\\n| Element Plus | 2.6.1 | UI 组件库 |\\n| Axios | 1.6.7 | HTTP 客户端 |\\n| Markdown-it | 14.0.0 | Markdown 渲染 |\\n| Highlight.js | 11.9.0 | 代码高亮 |\\n\\n#### 后台管理（Vue 2）\\n\\n| 技术 | 版本 | 说明 |\\n|---|---|---|\\n| Vue | 2.6.11 | 渐进式框架 |\\n| Element UI | 2.15.5 | UI 组件库 |\\n| Vuex | 3.4.0 | 状态管理 |\\n| Mavon-Editor | 2.9.0 | Markdown 编辑器 |\\n| ECharts | 4.8.0 | 数据可视化 |\\n\\n---\\n\\n## 🚀 快速开始\\n\\n### 环境要求\\n\\n- JDK 1.8+\\n- Maven 3.6+\\n- Node.js 14+\\n- MySQL 8.0+\\n- Redis 6.0+\\n\\n### 1. 克隆项目\\n\\n```bash\\ngit clone https://gitee.com/chen_fuyun/blog-satoken.git\\ncd blog-satoken\\n```\\n\\n### 2. 数据库初始化\\n\\n1. 创建数据库 `chen-blog`\\n2. 导入 SQL 脚本（联系作者获取或查看项目文档）\\n3. 修改后端配置文件 `renzs-blog-satoken/src/main/resources/application-dev.yml`：\\n\\n```yaml\\nspring:\\n  datasource:\\n    url: jdbc:mysql://localhost:3306/chen-blog?useSSL=false&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true\\n    username: root\\n    password: your_password\\n  redis:\\n    host: localhost\\n    port: 6379\\n    password: your_redis_password\\n```\\n\\n### 3. 启动后端\\n\\n```bash\\ncd renzs-blog-satoken\\nmvn clean install\\nmvn spring-boot:run\\n```\\n\\n后端服务默认运行在 `http://localhost:8088`\\n\\n### 4. 启动前端\\n\\n#### 博客前台（Vue 3）\\n\\n```bash\\ncd blog-front/blog-vue3\\nnpm install\\nnpm run dev\\n```\\n\\n前台服务运行在 `http://localhost:3000`\\n\\n#### 后台管理（Vue 2）\\n\\n```bash\\ncd blog-front/admin\\nnpm install\\nnpm run serve\\n```\\n\\n后台服务运行在 `http://localhost:8080`\\n\\n### 5. 访问系统\\n\\n- 博客前台：http://localhost:3000\\n- 后台管理：http://localhost:8080\\n- API 文档：http://localhost:8088/doc.html\\n\\n---\\n\\n## 📖 核心功能\\n\\n### 用户端功能\\n\\n- ✅ 用户注册、登录（账号密码 / QQ / 微博 / Gitee）\\n- ✅ 文章浏览、搜索、分类、标签\\n- ✅ 文章点赞、收藏、评论、回复\\n- ✅ 说说动态发布与互动\\n- ✅ 相册展示\\n- ✅ 在线聊天室\\n- ✅ 留言板\\n- ✅ 友情链接\\n- ✅ 关于页面\\n- ✅ 归档时间轴\\n- ✅ 主题切换（明暗模式）\\n\\n### 管理端功能\\n\\n- ✅ 文章管理（发布、编辑、删除、置顶）\\n- ✅ 分类 / 标签管理\\n- ✅ 评论管理（审核、删除）\\n- ✅ 用户管理（禁用、角色分配）\\n- ✅ 角色权限管理（RBAC）\\n- ✅ 菜单资源管理\\n- ✅ 友链管理\\n- ✅ 相册管理\\n- ✅ 说说管理\\n- ✅ 在线用户监控\\n- ✅ 操作日志\\n- ✅ 定时任务管理\\n- ✅ 数据统计（访问量、文章数、用户数）\\n\\n---\\n\\n## 🔐 鉴权机制\\n\\n本项目使用 [Sa-Token](https://sa-token.cc) 轻量级鉴权框架，相比 Spring Security：\\n\\n- **更简洁的 API**：`StpUtil.login()` / `StpUtil.checkPermission()`\\n- **更灵活的配置**：支持多账号体系、单点登录、OAuth2\\n- **更好的性能**：无复杂过滤器链，性能损耗小\\n\\n### 登录流程\\n\\n1. 前端提交账号密码到 `POST /login`\\n2. 后端验证密码（BCrypt）并调用 `StpUtil.login(userInfoId)`\\n3. Sa-Token 生成 token 并写入 Cookie（名称：`JSESSIONID`）\\n4. 后续请求自动携带 Cookie，Sa-Token 拦截器验证 token\\n\\n### 权限控制\\n\\n- **动态 URL 权限**：启动时从 `tb_resource` 表加载到 `ResourceRoleCache`\\n- **拦截器**：`SaInterceptor` 全局路由拦截\\n- **角色查询**：`StpInterfaceImpl.getRoleList()` 从数据库读取用户角色\\n- **业务侧获取登录用户**：`UserUtils.getLoginUser()`\\n\\n### API 说明\\n\\n| 方法 | URL | 说明 |\\n|---|---|---|\\n| POST | `/login` | 账号密码登录 |\\n| POST | `/logout` | 注销登录 |\\n| GET | `/users/current` | 获取当前登录用户信息 |\\n| POST | `/users/oauth/qq` | QQ 第三方登录 |\\n| POST | `/users/oauth/weibo` | 微博第三方登录 |\\n| POST | `/users/oauth/gitee` | Gitee 第三方登录 |\\n\\n---\\n\\n## 🎯 配置说明\\n\\n### 后端配置\\n\\n主要配置文件：`application-dev.yml`\\n\\n```yaml\\n# 数据库配置\\nspring:\\n  datasource:\\n    url: jdbc:mysql://localhost:3306/chen-blog\\n    username: root\\n    password: password\\n\\n# Redis 配置\\n  redis:\\n    host: localhost\\n    port: 6379\\n    password: \\n\\n# Sa-Token 配置\\nsa-token:\\n  token-name: JSESSIONID\\n  timeout: 2592000          # token 有效期（秒），默认 30 天\\n  active-timeout: -1        # token 临时有效期（秒），-1 表示禁用\\n  is-concurrent: true       # 是否允许同一账号并发登录\\n  is-share: false           # 多端登录是否共享 token\\n  token-style: uuid         # token 风格\\n  is-log: false             # 是否输出操作日志\\n\\n# Elasticsearch 配置（可选）\\n  elasticsearch:\\n    rest:\\n      uris: http://localhost:9200\\n\\n# 文件上传配置\\nupload:\\n  mode: oss                 # 上传模式：local / oss / cos\\n  oss:\\n    url: https://your-bucket.oss-cn-hangzhou.aliyuncs.com\\n    endpoint: oss-cn-hangzhou.aliyuncs.com\\n    accessKeyId: your-access-key-id\\n    accessKeySecret: your-access-key-secret\\n    bucketName: your-bucket\\n```\\n\\n### 前端配置\\n\\n博客前台 `.env` 文件：\\n\\n```env\\nVITE_APP_TITLE=Renzs Blog\\nVITE_API_BASE_URL=    # 留空，通过 Vite 代理转发\\n```\\n\\n后台管理无需额外配置，API 地址硬编码在 `axios` 实例中。\\n\\n---\\n\\n## 🧪 测试\\n\\n```bash\\ncd renzs-blog-satoken\\nmvn test\\n```\\n\\n测试覆盖：\\n- 登录 / 注销接口\\n- 鉴权拦截器\\n- 角色权限查询\\n- WebSocket 握手鉴权\\n- 第三方登录\\n\\n---\\n\\n## 📦 部署\\n\\n### 后端部署\\n\\n1. 修改 `application-pro.yml` 生产环境配置\\n2. 打包项目：\\n\\n```bash\\ncd renzs-blog-satoken\\nmvn clean package -DskipTests\\n```\\n\\n3. 运行 JAR 包：\\n\\n```bash\\njava -jar target/renzs-blog-satoken-0.0.1.jar --spring.profiles.active=pro\\n```\\n\\n4. 使用 Nginx 反向代理（可选）\\n\\n### 前端部署\\n\\n#### 博客前台\\n\\n```bash\\ncd blog-front/blog-vue3\\nnpm run build\\n```\\n\\n构建产物在 `dist/` 目录，部署到 Nginx 静态服务器。\\n\\n#### 后台管理\\n\\n```bash\\ncd blog-front/admin\\nnpm run build\\n```\\n\\n构建产物在 `dist/` 目录，部署到 Nginx 静态服务器。\\n\\n### Nginx 配置示例\\n\\n```nginx\\n# 后端 API\\nupstream blog-api {\\n    server 127.0.0.1:8088;\\n}\\n\\n# 博客前台\\nserver {\\n    listen 80;\\n    server_name yourdomain.com;\\n    \\n    root /var/www/blog-vue3/dist;\\n    index index.html;\\n    \\n    location / {\\n        try_files $uri $uri/ /index.html;\\n    }\\n    \\n    location /api {\\n        proxy_pass http://blog-api;\\n        proxy_set_header Host $host;\\n        proxy_set_header X-Real-IP $remote_addr;\\n    }\\n    \\n    location /ws {\\n        proxy_pass http://blog-api;\\n        proxy_http_version 1.1;\\n        proxy_set_header Upgrade $http_upgrade;\\n        proxy_set_header Connection \\"upgrade\\";\\n    }\\n}\\n\\n# 后台管理\\nserver {\\n    listen 80;\\n    server_name admin.yourdomain.com;\\n    \\n    root /var/www/admin/dist;\\n    index index.html;\\n    \\n    location / {\\n        try_files $uri $uri/ /index.html;\\n    }\\n    \\n    location /api {\\n        proxy_pass http://blog-api;\\n    }\\n}\\n```\\n\\n---\\n\\n## 🤝 贡献指南\\n\\n欢迎贡献代码、提交 Issue 或 Pull Request！\\n\\n### 贡献流程\\n\\n1. Fork 本仓库\\n2. 创建特性分支：`git checkout -b feature/AmazingFeature`\\n3. 提交更改：`git commit -m ''Add some AmazingFeature''`\\n4. 推送到分支：`git push origin feature/AmazingFeature`\\n5. 提交 Pull Request\\n\\n### 代码规范\\n\\n- 后端：遵循阿里巴巴 Java 开发手册\\n- 前端：使用 ESLint + Prettier 格式化代码\\n- 提交信息：遵循 Conventional Commits 规范\\n\\n---\\n\\n## 📝 更新日志\\n\\n详见 [CHANGELOG.md](renzs-blog-satoken/CHANGELOG.md)\\n\\n---\\n\\n## 📄 开源协议\\n\\n本项目基于 [MIT](LICENSE) 协议开源，可自由使用、修改、商用。\\n\\n---\\n\\n## 💬 联系方式\\n\\n- Gitee：https://gitee.com/chen_fuyun/blog-satoken\\n- GitHub：https://github.com/RenZSx/RenZS-blog\\n- Issue：https://gitee.com/chen_fuyun/blog-satoken/issues\\n\\n---\\n\\n## 🌟 致谢\\n\\n感谢以下开源项目：\\n\\n- [Spring Boot](https://spring.io/projects/spring-boot)\\n- [Sa-Token](https://sa-token.cc)\\n- [Vue.js](https://vuejs.org)\\n- [Element UI](https://element.eleme.io) / [Element Plus](https://element-plus.org)\\n- [Vuetify](https://vuetifyjs.com)\\n- [MyBatis-Plus](https://baomidou.com)\\n\\n---\\n\\n<div align=\\"center\\">\\n\\n如果这个项目对你有帮助，请点个 ⭐️ Star 支持一下！\\n\\n</div>\\n","articleCover":"https://static.renzs.top/articles/a79e6b68dda194ab8329dde1f54aea67.png","articleTitle":"博客开源了！","categoryName":"测试","id":96,"isTop":0,"seoDescription":"RenZS Blog 开源！基于 Sa Token 的前后端分离博客系统，功能完善，支持文章发布、评论、说说、相册、聊天，三端适配，欢迎体验。","seoKeywords":"博客开源,前后端分离博客,Sa Token博客系统,博客系统源码,个人博客","seoOgDescription":"RenZS Blog 开源啦！一个功能完善的个人博客系统，基于 Sa Token 轻量鉴权，支持文章、评论、说说、相册和在线聊天，快来体验吧！","seoTitle":"博客开源了！基于Sa Token前后端分离博客系统，支持文章、评论、聊天、相册","status":1,"tagNameList":[],"type":1}]', 'POST', '{"code":20000,"flag":true,"message":"操作成功"}', 1, '任子双', '127.0.0.1', '', '2026-08-13 15:34:52', NULL),
                                                                                                                                                                                                                                             (1731, '文章模块', '修改', '/admin/articles', 'com.chen.blog.module.article.controller.ArticleController.updateArticleDelete', '恢复或删除文章', '[{"idList":[92],"isDelete":1}]', 'PUT', '{"code":20000,"flag":true,"message":"操作成功"}', 1, '任子双', '127.0.0.1', '', '2026-08-13 15:39:20', NULL);

DROP TABLE IF EXISTS `tb_page`;

CREATE TABLE `tb_page` (
                           `id` int NOT NULL AUTO_INCREMENT COMMENT '页面id',
                           `page_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '页面名',
                           `page_label` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '页面标签',
                           `page_cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '页面封面',
                           `create_time` datetime NOT NULL COMMENT '创建时间',
                           `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                           PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=908 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='页面';

