DROP TABLE IF EXISTS `tb_sensitive_word`;

CREATE TABLE `tb_sensitive_word` (
                                     `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
                                     `word` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '敏感词',
                                     `word_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'default' COMMENT '敏感词类型',
                                     `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 0禁用 1启用',
                                     `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                     PRIMARY KEY (`id`),
                                     UNIQUE KEY `uk_word` (`word`),
                                     KEY `idx_word_type_status` (`word_type`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='敏感词表';

