DROP TABLE IF EXISTS `tb_system_notice`;

CREATE TABLE `tb_system_notice` (
                                    `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
                                    `content` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通知内容',
                                    `jump_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端跳转路径',
                                    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                    PRIMARY KEY (`id`),
                                    KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统通知表';

DROP TABLE IF EXISTS `tb_system_notice_read`;

CREATE TABLE `tb_system_notice_read` (
                                         `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
                                         `notice_id` bigint NOT NULL COMMENT '系统通知ID',
                                         `user_id` bigint NOT NULL COMMENT '用户ID',
                                         `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                         PRIMARY KEY (`id`),
                                         UNIQUE KEY `uk_notice_user` (`notice_id`,`user_id`),
                                         KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统通知已读表';

DROP TABLE IF EXISTS `tb_tag`;

CREATE TABLE `tb_tag` (
                          `id` int NOT NULL AUTO_INCREMENT,
                          `tag_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标签名',
                          `create_time` datetime NOT NULL COMMENT '创建时间',
                          `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                          PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

