DROP TABLE IF EXISTS `tb_talk`;

CREATE TABLE `tb_talk` (
                           `id` int NOT NULL AUTO_INCREMENT COMMENT '说说id',
                           `user_id` int NOT NULL COMMENT '用户id',
                           `content` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '说说内容',
                           `images` varchar(2500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片',
                           `is_top` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否置顶',
                           `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态 1.公开 2.私密',
                           `create_time` datetime NOT NULL COMMENT '创建时间',
                           `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                           PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=59 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

