DROP TABLE IF EXISTS `tb_user_notice`;

CREATE TABLE `tb_user_notice` (
                                  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
                                  `user_id` bigint NOT NULL COMMENT '用户ID',
                                  `notice_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通知类型',
                                  `source_id` bigint DEFAULT NULL COMMENT '来源记录ID',
                                  `source_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源模块',
                                  `target_id` bigint DEFAULT NULL COMMENT '最终跳转目标ID',
                                  `target_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最终跳转目标类型',
                                  `jump_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端跳转路径',
                                  `anchor_key` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端锚点键',
                                  `content` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通知内容',
                                  `reply_content` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '回复内容',
                                  `is_read` tinyint NOT NULL DEFAULT '0' COMMENT '是否已读 0未读 1已读',
                                  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                  PRIMARY KEY (`id`),
                                  KEY `idx_user_id` (`user_id`),
                                  KEY `idx_user_id_is_read` (`user_id`,`is_read`),
                                  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户通知表';

